import React, { useState, useRef, useEffect } from 'react';
import { MessageCircle, Send, X, Heart, Minus } from 'lucide-react';
import { Language, Message } from '../types';
import { translations } from '../translations';
import { getGeminiResponse } from '../services/geminiService';

const ChatWidget: React.FC<{ lang: Language }> = ({ lang }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: lang === 'es' ? '¡Hola! Soy tu asistente de Love Love. ¿Cómo puedo ayudarte hoy?' : 'Hello! I am your Love Love assistant. How can I help you today?' }
  ]);
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const t = translations[lang];

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg = input.trim();
    const newMessages: Message[] = [...messages, { role: 'user', text: userMsg }];
    setMessages(newMessages);
    setInput('');
    setIsLoading(true);

    const response = await getGeminiResponse(newMessages, lang);
    setMessages([...newMessages, { role: 'model', text: response }]);
    setIsLoading(false);
  };

  return (
    <div className="fixed bottom-6 right-6 z-[100] flex flex-col items-end">
      {isOpen ? (
        <div className="w-[350px] sm:w-[400px] h-[500px] bg-white rounded-3xl shadow-2xl flex flex-col overflow-hidden border border-[#e5989b]/30">
          {/* Header */}
          <div className="bg-[#6d1a1d] p-5 text-white flex items-center justify-between">
            <div className="flex items-center space-x-3">
              <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center">
                <Heart size={20} className="text-[#e5989b] fill-current" />
              </div>
              <div>
                <h3 className="font-bold text-sm">Love Love Care</h3>
                <p className="text-[10px] text-white/60 uppercase tracking-widest font-bold">Online</p>
              </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="hover:bg-white/10 p-1 rounded-full transition-colors">
              <Minus size={20} />
            </button>
          </div>

          {/* Messages */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 bg-[#faf3ef]/30">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] p-4 rounded-2xl text-sm leading-relaxed ${
                  m.role === 'user' 
                  ? 'bg-[#6d1a1d] text-white rounded-br-none' 
                  : 'bg-white text-[#6d1a1d] shadow-sm rounded-bl-none border border-[#e5989b]/20'
                }`}>
                  {m.text}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-white p-4 rounded-2xl shadow-sm border border-[#e5989b]/20 flex space-x-2">
                  <div className="w-2 h-2 bg-[#e5989b] rounded-full animate-bounce"></div>
                  <div className="w-2 h-2 bg-[#e5989b] rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                  <div className="w-2 h-2 bg-[#e5989b] rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                </div>
              </div>
            )}
          </div>

          {/* Input */}
          <div className="p-4 bg-white border-t border-pink-50">
            <div className="relative">
              <input 
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleSend()}
                placeholder={t.chatPlaceholder}
                className="w-full pl-4 pr-12 py-3 bg-[#faf3ef] rounded-2xl text-sm focus:outline-none focus:ring-2 focus:ring-[#e5989b]/50 transition-all text-[#6d1a1d]"
              />
              <button 
                onClick={handleSend}
                disabled={isLoading}
                className="absolute right-2 top-1/2 -translate-y-1/2 p-2 text-[#6d1a1d] hover:bg-white rounded-xl transition-all disabled:opacity-50"
              >
                <Send size={20} />
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="w-16 h-16 bg-[#6d1a1d] text-white rounded-full flex items-center justify-center shadow-2xl hover:bg-[#a32a2e] transition-all transform hover:scale-110 group relative"
        >
          <MessageCircle size={28} />
          <span className="absolute right-full mr-4 bg-white text-[#6d1a1d] text-xs font-bold py-2 px-4 rounded-xl shadow-xl whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none border border-[#e5989b]/20">
            {t.contactSupport}
          </span>
        </button>
      )}
    </div>
  );
};

export default ChatWidget;

import React from 'react';
import { X, Minus, Plus, ShoppingBag, Heart } from 'lucide-react';
import { Language, CartItem } from '../types';
import { translations } from '../translations';

interface CartDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  lang: Language;
  items: CartItem[];
  onUpdateQuantity: (id: string, delta: number) => void;
  onRemove: (id: string) => void;
}

const CartDrawer: React.FC<CartDrawerProps> = ({ isOpen, onClose, lang, items, onUpdateQuantity, onRemove }) => {
  const t = translations[lang];
  const subtotal = items.reduce((acc, item) => acc + (item.price * item.quantity), 0);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex justify-end">
      {/* Overlay */}
      <div className="absolute inset-0 bg-[#6d1a1d]/40 backdrop-blur-sm" onClick={onClose}></div>

      {/* Panel */}
      <div className="relative w-full max-w-md bg-[#fdfaf7] h-full shadow-2xl flex flex-col animate-slide-left">
        <div className="p-6 border-b border-[#e5989b]/20 flex items-center justify-between">
          <h2 className="font-serif text-2xl font-black text-[#6d1a1d] flex items-center">
            <ShoppingBag className="mr-2" /> {t.viewCart}
          </h2>
          <button onClick={onClose} className="p-2 hover:bg-[#e5989b]/10 rounded-full text-[#6d1a1d]">
            <X size={24} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-6">
          {items.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-center space-y-4 opacity-50">
              <Heart size={64} className="text-[#e5989b]" />
              <p className="text-[#6d1a1d] font-serif italic text-xl">{t.cartEmpty}</p>
            </div>
          ) : (
            items.map(item => (
              <div key={item.id} className="flex space-x-4 border-b border-[#e5989b]/10 pb-6">
                <img src={item.image} alt={item.name_en} className="w-24 h-32 object-cover rounded-xl shadow-sm" />
                <div className="flex-1 flex flex-col justify-between">
                  <div>
                    <h3 className="font-serif text-lg text-[#6d1a1d] leading-tight">
                      {lang === 'en' ? item.name_en : item.name_es}
                    </h3>
                    <p className="text-[#e5989b] font-black mt-1">${item.price.toFixed(2)}</p>
                  </div>
                  <div className="flex items-center justify-between">
                    <div className="flex items-center space-x-3 bg-white border border-pink-50 px-3 py-1 rounded-lg">
                      <button onClick={() => onUpdateQuantity(item.id, -1)} className="text-[#6d1a1d] hover:text-[#e5989b]"><Minus size={16} /></button>
                      <span className="font-bold text-sm min-w-[20px] text-center">{item.quantity}</span>
                      <button onClick={() => onUpdateQuantity(item.id, 1)} className="text-[#6d1a1d] hover:text-[#e5989b]"><Plus size={16} /></button>
                    </div>
                    <button onClick={() => onRemove(item.id)} className="text-xs text-red-500 uppercase tracking-widest font-bold">Remove</button>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>

        {items.length > 0 && (
          <div className="p-6 bg-white border-t border-[#e5989b]/20">
            <div className="flex justify-between items-center mb-6">
              <span className="text-lg font-serif italic text-[#6d1a1d]">{t.total}</span>
              <span className="text-3xl font-black text-[#6d1a1d]">${subtotal.toFixed(2)}</span>
            </div>
            <button className="w-full py-5 bg-[#6d1a1d] text-white rounded-2xl font-bold uppercase tracking-widest hover:bg-[#a32a2e] transition-all shadow-xl shadow-red-900/10">
              {t.checkout}
            </button>
            <p className="text-center text-[10px] text-[#6d1a1d]/50 mt-4 uppercase tracking-[0.2em]">
              {t.shippingInfo}
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

export default CartDrawer;

import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import ProductCard from './components/ProductCard';
import MissionSection from './components/MissionSection';
import ChatWidget from './components/ChatWidget';
import CartDrawer from './components/CartDrawer';
import { Language, Product, CartItem } from './types';
import { PRODUCTS } from './constants';
import { translations } from './translations';
import { Instagram, Facebook, Mail, MapPin } from 'lucide-react';

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('es');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const t = translations[lang];

  // Load cart from storage
  useEffect(() => {
    const saved = localStorage.getItem('lovelove_cart');
    if (saved) setCart(JSON.parse(saved));
  }, []);

  // Save cart to storage
  useEffect(() => {
    localStorage.setItem('lovelove_cart', JSON.stringify(cart));
  }, [cart]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) {
        return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
    setIsCartOpen(true);
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = Math.max(0, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  const removeProduct = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  return (
    <div className="min-h-screen selection:bg-[#e5989b] selection:text-white">
      {/* Structured Data for SEO */}
      <script type="application/ld+json">
        {JSON.stringify({
          "@context": "https://schema.org",
          "@type": "Store",
          "name": "Love Love",
          "url": "https://lovelove.ink",
          "logo": "https://lovelove.ink/logo.png",
          "description": "Ethical apparel and accessories spreading love over individualism.",
          "address": {
            "@type": "PostalAddress",
            "addressCountry": "Global"
          }
        })}
      </script>

      <Header 
        lang={lang} 
        setLang={setLang} 
        cart={cart} 
        onCartToggle={() => setIsCartOpen(true)} 
      />

      <main>
        <Hero lang={lang} />

        {/* Featured Section */}
        <section id="shop" className="py-24 max-w-7xl mx-auto px-4">
          <div className="text-center mb-16">
            <h2 className="font-serif text-4xl md:text-5xl font-black text-[#6d1a1d] mb-4">
              {t.featuredProducts}
            </h2>
            <div className="w-24 h-1 bg-[#e5989b] mx-auto rounded-full"></div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
            {PRODUCTS.map(product => (
              <ProductCard 
                key={product.id} 
                product={product} 
                lang={lang} 
                onAddToCart={addToCart} 
              />
            ))}
          </div>
        </section>

        <MissionSection lang={lang} />

        {/* Newsletter/Call to Action */}
        <section className="py-24 bg-[#faf3ef]">
          <div className="max-w-3xl mx-auto px-4 text-center">
            <h3 className="font-serif text-3xl md:text-4xl text-[#6d1a1d] mb-6">
              {lang === 'en' ? 'Stay in the Loop of Love' : 'Mantente en el círculo del amor'}
            </h3>
            <p className="text-[#6d1a1d]/70 mb-10 leading-relaxed italic">
              {lang === 'en' 
                ? 'Subscribe to get love notes, early access to new collections, and stories from our cause.' 
                : 'Suscríbete para recibir notas de amor, acceso anticipado y noticias de nuestra causa.'}
            </p>
            <div className="flex flex-col sm:flex-row gap-4">
              <input 
                type="email" 
                placeholder={lang === 'en' ? "Your heartfelt email" : "Tu correo con corazón"} 
