      4. Usa un lenguaje tierno y algún corazón ocasional ❤️.
      5. Si quieren comprar, diles que usen el botón de WhatsApp en el carrito.
    `;

    // Filtramos el historial para que la API reciba una secuencia correcta (User -> Model -> User)
    // El primer mensaje del historial suele ser el saludo del bot, lo saltamos para la API.
    const apiHistory = history.slice(1).map(msg => ({
      role: msg.role,
      parts: [{ text: msg.text }]
    }));

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: apiHistory,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.7,
      },
    });

    return response.text || (language === 'es' ? "Perdona, me distraje un momento. ¿Qué decías?" : "Sorry, I got a bit distracted. What were you saying?");
  } catch (error) {
    console.error("Gemini Error:", error);
    return language === 'es' 
      ? "Mi conexión falló, pero mi amor sigue aquí. ¿Podrías intentar de nuevo?" 
      : "My connection failed, but my heart is still here. Could you try again?";
  }
};

