export const getGeminiResponse = async (history: Message[], language: string) => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const systemInstruction = `
      Eres el asistente oficial de "Love Love" (lovelove.ink). 
      Tu personalidad: Cálida, empática, suave y profundamente comprometida con la causa de la marca.
      Filosofía: "Es tan sencillo por siempre amor, para siempre amor".
      Misión: Contrarrestar el individualismo con amor colectivo y ternura.

      Guías:
      1. Responde siempre en ${language === 'es' ? 'Español' : 'Inglés'}.
      2. Si preguntan por la marca, recalca que somos una tienda con causa.
      3. Productos: Alta calidad, producción bajo demanda ética vía Printful.
      4. Sé servicial pero nunca robótico. Usa lenguaje gentil y corazones (❤️).
      5. Si quieren comprar, guíales a la sección de tienda o al botón de finalizar pedido en el carrito.
    `;

    // Revertimos al envío del historial completo para mantener el contexto
    const contents = history.map(msg => ({
      role: msg.role,
      parts: [{ text: msg.text }]
    }));

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: contents,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.8,
        topP: 0.95,
      },
    });

    return response.text || (language === 'es' ? "Lo siento, tuve un pequeño problema. ¿Podrías repetirlo?" : "I'm sorry, I had a small glitch. Could you repeat that?");
  } catch (error) {
    console.error("Gemini Error:", error);
    return language === 'es' 
      ? "Algo salió mal, pero mi corazón sigue contigo. Por favor, intenta de nuevo." 
      : "Something went wrong, but our hearts are still with you. Please try again.";
  }
};

