              <span className="font-serif text-xl font-black text-[#6d1a1d]">Love Love</span>
            </div>
            <p className="text-[#6d1a1d]/60 max-w-sm mx-auto md:mx-0 leading-relaxed text-sm italic">"{t.mantra}"</p>
